use split_decls_genesis :: ourprelude :: * ; use crate :: fmt ; use crate :: iter :: { FusedIterator , TrustedLen } ; #[doc = " Creates an iterator that lazily generates a value exactly once by invoking"] #[doc = " the provided closure."] #[doc = ""] #[doc = " This is commonly used to adapt a single value coroutine into a [`chain()`] of"] #[doc = " other kinds of iteration. Maybe you have an iterator that covers almost"] #[doc = " everything, but you need an extra special case. Maybe you have a function"] #[doc = " which works on iterators, but you only need to process one value."] #[doc = ""] #[doc = " Unlike [`once()`], this function will lazily generate the value on request."] #[doc = ""] #[doc = " [`chain()`]: Iterator::chain"] #[doc = " [`once()`]: crate::iter::once"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Basic usage:"] #[doc = ""] #[doc = " ```"] #[doc = " use std::iter;"] #[doc = ""] #[doc = " // one is the loneliest number"] #[doc = " let mut one = iter::once_with(|| 1);"] #[doc = ""] #[doc = " assert_eq!(Some(1), one.next());"] #[doc = ""] #[doc = " // just one, that's all we get"] #[doc = " assert_eq!(None, one.next());"] #[doc = " ```"] #[doc = ""] #[doc = " Chaining together with another iterator. Let's say that we want to iterate"] #[doc = " over each file of the `.foo` directory, but also a configuration file,"] #[doc = " `.foorc`:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::iter;"] #[doc = " use std::fs;"] #[doc = " use std::path::PathBuf;"] #[doc = ""] #[doc = " let dirs = fs::read_dir(\".foo\").unwrap();"] #[doc = ""] #[doc = " // we need to convert from an iterator of DirEntry-s to an iterator of"] #[doc = " // PathBufs, so we use map"] #[doc = " let dirs = dirs.map(|file| file.unwrap().path());"] #[doc = ""] #[doc = " // now, our iterator just for our config file"] #[doc = " let config = iter::once_with(|| PathBuf::from(\".foorc\"));"] #[doc = ""] #[doc = " // chain the two iterators together into one big iterator"] #[doc = " let files = dirs.chain(config);"] #[doc = ""] #[doc = " // this will give us all of the files in .foo as well as .foorc"] #[doc = " for f in files {"] #[doc = "     println!(\"{f:?}\");"] #[doc = " }"] #[doc = " ```"] #[inline] #[stable (feature = "iter_once_with" , since = "1.43.0")] pub fn once_with < A , F : FnOnce () -> A > (make : F) -> OnceWith < F > { OnceWith { make : Some (make) } } #[doc = " An iterator that yields a single element of type `A` by"] #[doc = " applying the provided closure `F: FnOnce() -> A`."] #[doc = ""] #[doc = " This `struct` is created by the [`once_with()`] function."] #[doc = " See its documentation for more."] #[derive (Clone)] #[stable (feature = "iter_once_with" , since = "1.43.0")] pub struct OnceWith < F > { make : Option < F > , } #[stable (feature = "iter_once_with_debug" , since = "1.68.0")] impl < F > fmt :: Debug for OnceWith < F > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { if self . make . is_some () { f . write_str ("OnceWith(Some(_))") } else { f . write_str ("OnceWith(None)") } } } #[stable (feature = "iter_once_with" , since = "1.43.0")] impl < A , F : FnOnce () -> A > Iterator for OnceWith < F > { type Item = A ; #[inline] fn next (& mut self) -> Option < A > { let f = self . make . take () ? ; Some (f ()) } #[inline] fn size_hint (& self) -> (usize , Option < usize >) { self . make . iter () . size_hint () } } #[stable (feature = "iter_once_with" , since = "1.43.0")] impl < A , F : FnOnce () -> A > DoubleEndedIterator for OnceWith < F > { fn next_back (& mut self) -> Option < A > { self . next () } } #[stable (feature = "iter_once_with" , since = "1.43.0")] impl < A , F : FnOnce () -> A > ExactSizeIterator for OnceWith < F > { fn len (& self) -> usize { self . make . iter () . len () } } #[stable (feature = "iter_once_with" , since = "1.43.0")] impl < A , F : FnOnce () -> A > FusedIterator for OnceWith < F > { } #[stable (feature = "iter_once_with" , since = "1.43.0")] unsafe impl < A , F : FnOnce () -> A > TrustedLen for OnceWith < F > { }